/* Unlayered on purpose: owned properties must beat Tailwind utilities. */
.layout-stack {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: var(--align, stretch);
  gap: var(--space, calc(var(--spacing, 0.25rem) * 4));
}

.layout-stack[data-split="1"] > :nth-child(1),
.layout-stack[data-split="2"] > :nth-child(2),
.layout-stack[data-split="3"] > :nth-child(3),
.layout-stack[data-split="4"] > :nth-child(4),
.layout-stack[data-split="5"] > :nth-child(5),
.layout-stack[data-split="6"] > :nth-child(6),
.layout-stack[data-split="7"] > :nth-child(7),
.layout-stack[data-split="8"] > :nth-child(8) {
  margin-block-end: auto;
}

/* Unlayered on purpose: owned properties must beat Tailwind utilities. */
.layout-cluster {
  display: flex;
  flex-wrap: wrap;
  align-items: var(--align, center);
  justify-content: var(--justify, flex-start);
  gap: var(--space, calc(var(--spacing, 0.25rem) * 4));
}

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  type Length,
  type PolyProps,
  type Spacing,
  layoutRoot,
  toLength,
  toSpace,
  warnMissingSlots,
} from "./layout"

import "./aside.css"

function AsideSide<T extends React.ElementType = "div">({
  className,
  as,
  asChild,
  children,
  ...props
}: PolyProps<T, object>) {
  return layoutRoot(
    as,
    asChild,
    {
      ...props,
      "data-slot": "aside-side",
      className: cn(className),
    },
    children
  )
}

function AsideContent<T extends React.ElementType = "div">({
  className,
  as,
  asChild,
  children,
  ...props
}: PolyProps<T, object>) {
  return layoutRoot(
    as,
    asChild,
    {
      ...props,
      "data-slot": "aside-content",
      className: cn(className),
    },
    children
  )
}

function AsideRoot<T extends React.ElementType = "div">({
  className,
  space = "4",
  sideWidth = "20rem",
  contentMin = "50%",
  side = "start",
  as,
  asChild,
  children,
  style,
  ...props
}: PolyProps<
  T,
  {
    space?: Spacing
    sideWidth?: Length
    contentMin?: Length
    side?: "start" | "end"
  }
>) {
  warnMissingSlots("Aside", children, [
    { label: "Aside.Side", type: AsideSide },
    { label: "Aside.Content", type: AsideContent },
  ])

  return layoutRoot(
    as,
    asChild,
    {
      ...props,
      "data-slot": "aside",
      "data-side": side,
      className: cn("layout-aside", className),
      style: {
        "--space": toSpace(space),
        "--side-width": toLength(sideWidth),
        "--content-min": toLength(contentMin),
        ...style,
      },
    },
    children
  )
}

const Aside = Object.assign(AsideRoot, {
  Side: AsideSide,
  Content: AsideContent,
})

export { Aside, AsideContent, AsideSide }

/* Unlayered on purpose: owned properties must beat Tailwind utilities. */
.layout-aside {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: var(--space, calc(var(--spacing, 0.25rem) * 4));
}

.layout-aside > [data-slot="aside-side"] {
  flex-basis: var(--side-width, 20rem);
  flex-grow: 1;
}

.layout-aside > [data-slot="aside-content"] {
  flex-basis: 0;
  flex-grow: 999;
  min-inline-size: min(100%, var(--content-min, 50%));
}

.layout-aside[data-side="end"] > [data-slot="aside-side"] {
  order: 1;
}

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  type Length,
  type PolyProps,
  type Spacing,
  layoutRoot,
  toLength,
  toSpace,
} from "./layout"

import "./switcher.css"

export function Switcher<T extends React.ElementType = "div">({
  className,
  space = "4",
  threshold = "30rem",
  limit,
  as,
  asChild,
  children,
  style,
  ...props
}: PolyProps<
  T,
  {
    space?: Spacing
    threshold?: Length
    limit?: 2 | 3 | 4 | 5 | 6
  }
>) {
  return layoutRoot(
    as,
    asChild,
    {
      ...props,
      "data-slot": "switcher",
      "data-limit": limit,
      className: cn("layout-switcher", className),
      style: {
        "--space": toSpace(space),
        "--threshold": toLength(threshold),
        ...style,
      },
    },
    children
  )
}

/* Unlayered on purpose: owned properties must beat Tailwind utilities. */
.layout-switcher {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space, calc(var(--spacing, 0.25rem) * 4));
}

.layout-switcher > * {
  flex-grow: 1;
  flex-basis: calc((var(--threshold, 30rem) - 100%) * 999);
}

.layout-switcher[data-limit="2"] > :nth-last-child(n + 3),
.layout-switcher[data-limit="2"] > :nth-last-child(n + 3) ~ *,
.layout-switcher[data-limit="3"] > :nth-last-child(n + 4),
.layout-switcher[data-limit="3"] > :nth-last-child(n + 4) ~ *,
.layout-switcher[data-limit="4"] > :nth-last-child(n + 5),
.layout-switcher[data-limit="4"] > :nth-last-child(n + 5) ~ *,
.layout-switcher[data-limit="5"] > :nth-last-child(n + 6),
.layout-switcher[data-limit="5"] > :nth-last-child(n + 6) ~ *,
.layout-switcher[data-limit="6"] > :nth-last-child(n + 7),
.layout-switcher[data-limit="6"] > :nth-last-child(n + 7) ~ * {
  flex-basis: 100%;
}

