  T,
  {
    measure?: Measure
    gutters?: Spacing
    intrinsic?: boolean
  }
>) {
  return layoutRoot(
    as,
    asChild,
    {
      ...props,
      "data-slot": "center",
      "data-intrinsic": intrinsic ? "" : undefined,
      className: cn("layout-center", className),
      style: {
        "--measure": toMeasure(measure),
        "--gutters": toSpace(gutters),
        ...style,
      },
    },
    children
